from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 230, "מבט מלמעלה: קיר מקביל לציר y. מהנקודה O נעים שני חלקיקים: חלקיק 1 פוגע בקיר בניצב לו, וחלקיק 2 פוגע בקיר בזווית אלפא וחוזר בזווית בטא")
    g.add('<line x1="40" y1="200" x2="420" y2="200" stroke="var(--d-line)" stroke-width="1.6" marker-end="url(#f-axis)"/>'); g.add('<line x1="40" y1="200" x2="40" y2="20" stroke="var(--d-line)" stroke-width="1.6" marker-end="url(#f-axis)"/>')
    g.text(426, 204, "x", anchor="start"); g.text(46, 26, "y", anchor="start")
    g.rect(380, 30, 10, 160, fill="var(--d-label)", stroke="none", width=0)
    g.dot(100, 130); g.text(90, 134, "O", anchor="end")
    g.arrow(100, 130, 376, 130, "1", lx=240, ly=146)
    g.arrow(100, 130, 376, 70, "2", lx=230, ly=92)
    g.line(376, 70, 220, 36, stroke="var(--d-line)", width=1.6)
    g.text(360, 86, "α", anchor="end"); g.text(360, 60, "β", anchor="end")
    return g

E(id="bagrut-1995-q4", year=1995, label="1995 שאלה 4", topic="momentum", sub="mom-impulse", diff=3, fig=fig,
  stem=r"בתרשים רואים מלמעלה קיר שמקביל לציר $y$. מהנקודה $O$ שעל הרצפה משגרים שני חלקיקים, והם נעים על הרצפה בלי חיכוך. חלקיק 1 פוגע בקיר בניצב לו, וחלקיק 2 פוגע בקיר בזווית $\alpha$ ביחס לקיר. לכל חלקיק מסה $m$, ולשניהם אותו גודל מהירות $v$. כל חלקיק מתנגש בקיר התנגשות אלסטית, בלי חיכוך עם הקיר, ולכן הכוח שהקיר מפעיל על החלקיק ניצב לקיר. הקיר כבד מאוד ולא זז. הכיוון החיובי של ציר $x$ הוא לכיוון הקיר. כתבו את התשובות בעזרת נתוני השאלה.",
  parts=[
    P("א", r"מה המהירות (גודל וכיוון) של חלקיק 1 אחרי שהוא פוגע בקיר? נמקו.", choice([r"$-v$: אותו גודל, בכיוון ההפוך", r"$v$: אותו גודל ואותו כיוון", r"$0$: החלקיק נעצר", r"$-2v$: כפליים, בכיוון ההפוך"], 0), ["principle", "signs"], [
        S(r"התנגשות אלסטית בגוף כבד מאוד", r"הקיר לא זז, ולכן הוא לא מקבל אנרגיה. האנרגיה הקינטית של החלקיק נשמרת, ולכן גודל המהירות נשמר. הקיר דוחף את החלקיק אחורה, ולכן הכיוון מתהפך", r"\tfrac{1}{2}mv^2 = \tfrac{1}{2}mu_1^2 \;\Rightarrow\; u_1 = -v", eq=r"E_k = \tfrac{1}{2}mv^2"),
    ], r"$-v$: אותו גודל, בכיוון ההפוך", key=r"−v"),
    P("ב", r"מה השינוי בתנע של חלקיק 1 בגלל הפגיעה בקיר?", choice([r"$-2mv$", r"$0$", r"$-mv$", r"$2mv$"], 0), ["principle", "signs"], [
        S(r"שינוי התנע", r"התנע הסופי פחות התנע ההתחלתי, עם הסימנים", r"\Delta p = m(-v) - m v = -2mv", eq=r"\vec p = m\vec v"),
    ], r"$-2mv$, כלומר בכיוון השלילי של ציר $x$", key=r"−2mv"),
    P("ג", r"מה גודל המהירות של חלקיק 2 אחרי הפגיעה בקיר? נמקו.", choice([r"$v$", r"$v\sin\alpha$", r"$v\cos\alpha$", r"$0$"], 0), ["principle"], [
        S(r"שימור אנרגיה", r"ההתנגשות אלסטית והקיר לא זז, ולכן האנרגיה הקינטית של החלקיק נשמרת", r"\tfrac{1}{2}mv^2 = \tfrac{1}{2}mu_2^2 \;\Rightarrow\; |u_2| = v", eq=r"E_k = \tfrac{1}{2}mv^2"),
    ], r"$v$: הגודל לא משתנה", key=r"גודל המהירות לא השתנה"),
    P("ד", r"אחרי הפגיעה חלקיק 2 נע במסלול שיוצר זווית $\beta$ עם הקיר. הוכיחו שהזווית $\alpha$ שווה לזווית $\beta$.", OPEN, ["principle"], [
        S(r"הרכיב המקביל לקיר", r"הקיר חלק, ולכן הוא לא מפעיל כוח במקביל אליו. הרכיב הזה של המהירות לא משתנה", r"v\cos\alpha = v\cos\beta"),
        S(r"מסקנה", r"גודל המהירות לא השתנה, מהסעיף הקודם. לכן גם הקוסינוסים שווים", r"\cos\alpha = \cos\beta \;\Rightarrow\; \alpha = \beta"),
    ], r"הרכיב המקביל לקיר וגודל המהירות לא משתנים, ולכן $\alpha = \beta$"),
    P("ה", r"מה המתקף שהקיר הפעיל על חלקיק 2?", choice([r"$-2mv\sin\alpha$", r"$-2mv\cos\alpha$", r"$-2mv$", r"$0$"], 0), ["principle", "signs"], [
        S(r"רק הרכיב הניצב לקיר משתנה", r"הזווית נמדדת מהקיר, ולכן הרכיב הניצב לקיר הוא עם סינוס. הוא מתהפך, והרכיב המקביל לא משתנה", r"v_x = v\sin\alpha \;\to\; u_x = -v\sin\alpha"),
        S(r"המתקף", r"המתקף שווה לשינוי התנע", r"J = m(-v\sin\alpha) - m\,v\sin\alpha = -2mv\sin\alpha", eq=r"\vec J_{\text{tot}} = \Delta\vec p"),
    ], r"$-2mv\sin\alpha$, בניצב לקיר והחוצה ממנו", key=r"−2mv·sinα"),
  ],
  concepts=["התנגשות אלסטית בקיר", "מתקף", "שינוי תנע ברכיבים", "זווית פגיעה וזווית החזרה"],
  summary=r"חלקיקים שפוגעים בקיר: רק הרכיב הניצב מתהפך, ולכן זווית ההחזרה שווה לזווית הפגיעה.",
  review="הנחה שלי.\nהזווית אלפא נמדדת ביחס לקיר, ולכן התשובה בדף התשובות יוצאת עם סינוס. בסעיפים א, ב, ג ו-ה התלמיד בוחר את הביטוי הנכון מתוך ארבעה. הוספתי לנוסח שהכיוון החיובי הוא לכיוון הקיר, כדי שהסימן בתשובה יהיה חד-משמעי.\nמה לבדוק: רק לאשר.")
